package com.voicescape;

import java.nio.charset.StandardCharsets;
import java.security.InvalidKeyException;
import java.security.NoSuchAlgorithmException;
import java.util.Base64;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import lombok.extern.slf4j.Slf4j;

@Slf4j
public class HashUtil
{
	private static final String HMAC_ALGO = "HmacSHA256";

	public static String hmac(byte[] key, String playerName)
	{
		try
		{
			Mac mac = Mac.getInstance(HMAC_ALGO);
			mac.init(new SecretKeySpec(key, HMAC_ALGO));
			byte[] hash = mac.doFinal(playerName.getBytes(StandardCharsets.UTF_8));
			return Base64.getEncoder().encodeToString(hash);
		}
		catch (NoSuchAlgorithmException | InvalidKeyException e)
		{
			log.error("HMAC computation failed", e);
			throw new RuntimeException("HMAC computation failed", e);
		}
	}
}

package com.voicescape;

public class AudioCodec {

    public static int encode(short[] pcm, byte[] out) {
        int outIdx = 0;
        short lastSample = 0;

        for (short sample : pcm) {
            int delta = sample - lastSample;
            lastSample = sample;

            int n = (delta << 1) ^ (delta >> 31);

            while ((n & ~0x7F) != 0) {
                out[outIdx++] = (byte) ((n & 0x7F) | 0x80);
                n >>>= 7;
            }
            out[outIdx++] = (byte) n;
        }
        return outIdx;
    }


    public static void decode(byte[] in, int inOffset, int inLength, short[] pcm) {
        int inIdx = inOffset;
        int endIdx = inOffset + inLength;
        short lastSample = 0;
        int pcmIdx = 0;

        while (inIdx < endIdx && pcmIdx < pcm.length) {
            int n = 0;
            int shift = 0;
            byte b;
            do {
                if (inIdx >= endIdx) break;
                b = in[inIdx++];
                n |= (b & 0x7F) << shift;
                shift += 7;
            } while ((b & 0x80) != 0);

            int delta = (n >>> 1) ^ -(n & 1);
            short sample = (short) (lastSample + delta);
            pcm[pcmIdx++] = sample;
            lastSample = sample;
        }
    }
}

package com.voicescape;


import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;

import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.DataLine;
import javax.sound.sampled.Mixer;
import javax.sound.sampled.TargetDataLine;
import java.util.Arrays;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
public class AudioCaptureThread
{
	private final VoiceChatConfig config;
	private final NetworkClient networkClient;
	private final AudioPlaybackManager playbackManager;
	private final AtomicBoolean running = new AtomicBoolean(false);
	private ScheduledExecutorService scheduler;
	private Future<?> captureTask;
	private static final int HANGOVER_FRAMES = 40;
	private static final int VAD_PREROLL_FRAMES = 8;

	private static final int TAIL_SILENCE_FRAMES = 10;

	@Setter
    private volatile boolean pttActive = false;
	@Getter
    private volatile boolean transmitting = false;
	@Setter
    private volatile boolean hasNearbyPlayers = false;
	private boolean wasTransmitting = false;
	private int hangoverRemaining = 0;
	private int tailSilenceRemaining = 0;
	private final byte[][] prerollBuffer = new byte[VAD_PREROLL_FRAMES][];
	private int prerollIndex = 0;
	private int prerollCount = 0;
	private TargetDataLine line;

	private final short[] pcmShortsBuffer = new short[AudioDeviceManager.FRAME_SIZE_BYTES / 2];
	private final byte[] gainByteBuffer = new byte[AudioDeviceManager.FRAME_SIZE_BYTES];
	private final byte[] losslessOutputBuffer = new byte[AudioDeviceManager.FRAME_SIZE_BYTES * 3];

	public AudioCaptureThread(VoiceChatConfig config, NetworkClient networkClient, AudioPlaybackManager playbackManager)
	{
		this.config = config;
		this.networkClient = networkClient;
		this.playbackManager = playbackManager;
	}

	public synchronized void start()
	{
		if (running.get())
		{
			return;
		}

		running.set(true);
		scheduler = Executors.newSingleThreadScheduledExecutor(r ->
		{
			Thread thread = new Thread(r, "VoiceScape-Capture");
			thread.setDaemon(true);
			return thread;
		});
		captureTask = scheduler.submit(this::captureLoop);
	}

    public void openLine()
	{
		try
		{
			DataLine.Info info = new DataLine.Info(TargetDataLine.class, AudioDeviceManager.FORMAT);

			String deviceName = config.inputDevice();
			if (deviceName != null && !deviceName.isEmpty())
			{
				Mixer.Info mixerInfo = AudioDeviceManager.findMixer(deviceName, true);
				if (mixerInfo != null)
				{
					Mixer mixer = AudioSystem.getMixer(mixerInfo);
					line = (TargetDataLine) mixer.getLine(info);
				}
				else
				{
					log.debug("Input device '{}' not found, falling back to default", deviceName);
					line = (TargetDataLine) AudioSystem.getLine(info);
				}
			}
			else
			{
				line = (TargetDataLine) AudioSystem.getLine(info);
			}

			line.open(AudioDeviceManager.FORMAT);
			line.start();
			log.debug("Audio capture line opened");
		}
		catch (Exception e)
		{
			log.debug("Failed to open audio capture line", e);
			line = null;
		}
	}

	private void captureLoop()
	{
		openLine();

		if (line == null)
		{
			log.debug("No capture line available, capture thread exiting");
			running.set(false);
			return;
		}

		byte[] buffer = new byte[AudioDeviceManager.FRAME_SIZE_BYTES];

		while (running.get())
		{
			try
			{
				if(line == null)
					continue;

				int bytesRead = line.read(buffer, 0, buffer.length);
				if (bytesRead <= 0)
				{
					continue;
				}

				if (config.muted())
				{
					transmitting = false;
					continue;
				}

				double rms = calculateRmsAndApplyGain(buffer, bytesRead, gainByteBuffer, config.micGain());

				boolean voiceActive;
				if (config.voiceMode() == VoiceMode.PUSH_TO_TALK)
				{
					voiceActive = pttActive;
				}
				else
				{
					voiceActive = isAboveThreshold(rms);
				}

				boolean shouldTransmit = false;
				boolean sendSilence = false;

				if (voiceActive)
				{
					hangoverRemaining = HANGOVER_FRAMES;
					tailSilenceRemaining = TAIL_SILENCE_FRAMES;
					shouldTransmit = true;
				}
				else if (hangoverRemaining > 0)
				{
					hangoverRemaining--;
					shouldTransmit = true;
				}
				else if (tailSilenceRemaining > 0)
				{
					tailSilenceRemaining--;
					sendSilence = true;
				}

				transmitting = shouldTransmit || sendSilence;

				byte[] pcm = gainByteBuffer;

				if (sendSilence)
				{
					if (networkClient.isConnected() && hasNearbyPlayers)
					{
						try
						{
                            Arrays.fill(gainByteBuffer, (byte) 0);
							encodeAndSend(gainByteBuffer);
						}
						catch (Exception e)
						{
							// Ignored
						}
					}
					if (tailSilenceRemaining == 0)
					{
						wasTransmitting = false;
						playbackManager.flushLine();
					}
					continue;
				}

				if (!shouldTransmit)
				{
					if (config.voiceMode() != VoiceMode.PUSH_TO_TALK)
					{
						prerollBuffer[prerollIndex] = pcm.clone();
						prerollIndex = (prerollIndex + 1) % VAD_PREROLL_FRAMES;
						if (prerollCount < VAD_PREROLL_FRAMES)
						{
							prerollCount++;
						}
					}

					if (wasTransmitting)
					{
						wasTransmitting = false;
						playbackManager.flushLine();
					}
					continue;
				}

				if (!wasTransmitting && prerollCount > 0)
				{
					int start = (prerollIndex - prerollCount + VAD_PREROLL_FRAMES) % VAD_PREROLL_FRAMES;
					for (int i = 0; i < prerollCount; i++)
					{
						int idx = (start + i) % VAD_PREROLL_FRAMES;
						byte[] prerollPcm = prerollBuffer[idx];
						if (prerollPcm == null)
						{
							continue;
						}
						prerollBuffer[idx] = null;

						if (config.localLoopback())
						{
							playbackManager.receiveLoopback(prerollPcm);
						}

						if (networkClient.isConnected() && hasNearbyPlayers)
						{
							try
							{
								encodeAndSend(prerollPcm);
							}
							catch (Exception e)
							{
								// Ignored
							}
						}
					}
					prerollCount = 0;
				}
				wasTransmitting = true;

				if (config.localLoopback())
				{
					playbackManager.receiveLoopback(pcm);
				}

				if (networkClient.isConnected() && hasNearbyPlayers)
				{
					encodeAndSend(pcm);
				}
			}
			catch (Exception e)
			{
				log.debug("Error in audio capture loop", e);
			}
		}

		closeLine();
		running.set(false);
	}

	private void encodeAndSend(byte[] pcm) {
		AudioDeviceManager.bytesToShorts(pcm, pcm.length, pcmShortsBuffer);
		int encodedLength = AudioCodec.encode(pcmShortsBuffer, losslessOutputBuffer);

		byte[] finalPayload = new byte[encodedLength];
		System.arraycopy(losslessOutputBuffer, 0, finalPayload, 0, encodedLength);

		networkClient.sendAudioFrame(networkClient.nextSequenceNumber(), finalPayload);
	}

	public void shutdown()
	{
		running.set(false);
		closeLine();

		if (captureTask != null)
		{
			captureTask.cancel(true);
			captureTask = null;
		}
		if (scheduler != null)
		{
			scheduler.shutdownNow();
			scheduler = null;
		}
	}

	public void closeLine()
	{
		if (line != null)
		{
			try
			{
				line.stop();
				line.close();
			}
			catch (Exception e)
			{
				log.debug("Error closing capture line", e);
			}
			line = null;
		}
	}

	private double calculateRmsAndApplyGain(byte[] input, int length, byte[] output, int gainPercent) {
		double rms = 0;
		int samples = length / 2;
		double gain = gainPercent / 100.0;

		for (int i = 0; i < length - 1; i += 2) {
			int sample = (input[i] & 0xFF) | (input[i + 1] << 8);
			if (sample > 32767) sample -= 65536;

			rms += (double)sample * sample;
			if (gain != 1.0) {
				sample = (int) Math.max(-32768, Math.min(32767, sample * gain));
			}

			output[i] = (byte) (sample & 0xFF);
			output[i + 1] = (byte) ((sample >> 8) & 0xFF);
		}
		return Math.sqrt(rms / samples);
	}

	private boolean isAboveThreshold(double rms)
	{
		double t = config.vadSensitivity() / 100.0;
		double threshold = 5.0 + (t * t) * 10000;
		return rms > threshold;
	}
}

package com.voicescape;

import lombok.extern.slf4j.Slf4j;

@Slf4j
public class JitterBuffer
{
	private static final int BUFFER_SIZE = 64;
	private static final int MASK = BUFFER_SIZE - 1;

	private static final int PREBUFFER_FRAMES = 10;

	private final byte[][] slots = new byte[BUFFER_SIZE][];
	private final boolean[] occupied = new boolean[BUFFER_SIZE];
	private int nextReadSeq = -1;
	private int maxReceivedSeq = -1;
	private boolean primed = false;

    public synchronized void put(int sequenceNumber, byte[] opusPayload)
	{
		if (nextReadSeq == -1)
		{
			nextReadSeq = sequenceNumber;
		}

		if (sequenceNumber < nextReadSeq)
		{
			return;
		}

		if (sequenceNumber >= nextReadSeq + BUFFER_SIZE)
		{
			for (int i = 0; i < BUFFER_SIZE; i++)
			{
				slots[i] = null;
				occupied[i] = false;
			}
			nextReadSeq = sequenceNumber;
			maxReceivedSeq = -1;
			primed = false;
        }

		int idx = sequenceNumber & MASK;
		slots[idx] = opusPayload;
		occupied[idx] = true;

		if (sequenceNumber > maxReceivedSeq)
		{
			maxReceivedSeq = sequenceNumber;
		}
	}

	public synchronized boolean isReady()
	{
		if (primed)
		{
			return true;
		}
		if (bufferedCount() >= PREBUFFER_FRAMES)
		{
			primed = true;
			return true;
		}
		return false;
	}

	public synchronized boolean canPoll()
	{
		if (nextReadSeq == -1)
		{
			return false;
		}
		int idx = nextReadSeq & MASK;
		if (occupied[idx])
		{
			return true;
		}
		return nextReadSeq < maxReceivedSeq;
	}

	public synchronized byte[] poll()
	{
		if (nextReadSeq == -1)
		{
			return null;
		}

		int idx = nextReadSeq & MASK;
		if (occupied[idx])
		{
			byte[] data = slots[idx];
			slots[idx] = null;
			occupied[idx] = false;
			nextReadSeq++;
			return data;
		}

		if (nextReadSeq < maxReceivedSeq)
		{
			nextReadSeq++;
			return null;
		}
		return null;
	}

	public synchronized void reset()
	{
		for (int i = 0; i < BUFFER_SIZE; i++)
		{
			slots[i] = null;
			occupied[i] = false;
		}
		nextReadSeq = -1;
		maxReceivedSeq = -1;
		primed = false;
	}

	public synchronized int bufferedCount()
	{
		int count = 0;
		for (boolean b : occupied)
		{
			if (b) count++;
		}
		return count;
	}
}

package com.voicescape;

import lombok.Getter;
import lombok.extern.slf4j.Slf4j;

import javax.sound.sampled.AudioSystem;
import javax.sound.sampled.DataLine;
import javax.sound.sampled.Mixer;
import javax.sound.sampled.SourceDataLine;
import java.util.Collections;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.Executors;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

@Slf4j
public class AudioPlaybackManager {
	private static final int MAX_SPEAKERS = 10;
	private static final int FRAME_SIZE_SAMPLES = AudioDeviceManager.FRAME_SIZE_BYTES / 2;

	private final VoiceChatConfig config;
	private final AtomicBoolean running = new AtomicBoolean(false);
	private ScheduledExecutorService scheduler;
	private ScheduledFuture<?> playbackTask;
	private final Map<String, SpeakerState> speakers = new ConcurrentHashMap<>();
	@Getter
	private final Set<String> activeSpeakers = ConcurrentHashMap.newKeySet();
	@Getter
	private final Set<String> mutedHashes = ConcurrentHashMap.newKeySet();
	@Getter
	private final Set<String> unmutedDefaultHashes = ConcurrentHashMap.newKeySet();
	private volatile Map<String, Integer> nearbyDistances = Collections.emptyMap();
	private SourceDataLine line;

	private final short[] decodedBuffer = new short[AudioDeviceManager.FRAME_SIZE_BYTES / 2];
	private final short[] loopbackShortBuffer = new short[AudioDeviceManager.FRAME_SIZE_BYTES / 2];
	private final byte[] outputByteBuffer = new byte[AudioDeviceManager.FRAME_SIZE_BYTES];

	public AudioPlaybackManager(VoiceChatConfig config) {
		this.config = config;
	}

	public synchronized void start() {
		if (running.get()) {
			return;
		}

		running.set(true);
		scheduler = Executors.newSingleThreadScheduledExecutor(r -> {
			Thread thread = new Thread(r, "VoiceScape-Playback");
			thread.setDaemon(true);
			return thread;
		});
		scheduler.execute(() -> {
			openLine();
			if (line == null) {
				log.debug("No playback line available, playback scheduler exiting");
				running.set(false);
				scheduler.shutdown();
				return;
			}

			playbackTask = scheduler.scheduleWithFixedDelay(
				this::playbackTick,
				0,
				10,
				TimeUnit.MILLISECONDS);
		});
	}

	public void flushLine() {
		SourceDataLine l = line;
		if (l != null) {
			l.flush();
		}
	}

	public void clearMutedPlayers() {
		mutedHashes.clear();
	}

	public void mutePlayer(String hash) {
		mutedHashes.add(hash);
	}

	public void unmutePlayer(String hash) {
		mutedHashes.remove(hash);
	}

	public boolean isPlayerMuted(String hash) {
		return mutedHashes.contains(hash);
	}

	public void updateNearbyDistances(Map<String, Integer> distances) {
		this.nearbyDistances = distances;
	}

	public void receiveLoopback(byte[] pcm) {
		if (config.deafened() || line == null) {
			return;
		}

		double volume = (config.outputVolume() / 100.0);

		AudioDeviceManager.bytesToShorts(pcm, pcm.length, loopbackShortBuffer);

		for (int i = 0; i < loopbackShortBuffer.length; i++) {
			loopbackShortBuffer[i] = (short) Math.max(-32768, Math.min(32767, loopbackShortBuffer[i] * volume));
		}

		AudioDeviceManager.shortsToBytes(loopbackShortBuffer, outputByteBuffer);
		line.write(outputByteBuffer, 0, outputByteBuffer.length);
	}

	public void receiveAudio(String senderIdentityHash, int sequenceNumber, byte[] payload) {
		if (config.deafened() || mutedHashes.contains(senderIdentityHash)) {
			return;
		}

		if (!speakers.containsKey(senderIdentityHash) && speakers.size() >= MAX_SPEAKERS) {
			return;
		}

		SpeakerState state = speakers.computeIfAbsent(senderIdentityHash, k -> new SpeakerState());

		state.jitterBuffer.put(sequenceNumber, payload);
		state.lastReceiveTime = System.currentTimeMillis();
	}

	public void openLine() {
		try {
			DataLine.Info info = new DataLine.Info(SourceDataLine.class, AudioDeviceManager.FORMAT);

			String deviceName = config.outputDevice();
			if (deviceName != null && !deviceName.isEmpty()) {
				Mixer.Info mixerInfo = AudioDeviceManager.findMixer(deviceName, false);
				if (mixerInfo != null) {
					Mixer mixer = AudioSystem.getMixer(mixerInfo);
					line = (SourceDataLine) mixer.getLine(info);
				} else {
					log.debug("Output device '{}' not found, falling back to default", deviceName);
					line = (SourceDataLine) AudioSystem.getLine(info);
				}
			} else {
				line = (SourceDataLine) AudioSystem.getLine(info);
			}

			int bufferBytes = AudioDeviceManager.FRAME_SIZE_BYTES * 8;
			line.open(AudioDeviceManager.FORMAT, bufferBytes);
			line.start();
			log.debug("Audio playback line opened (buffer {} bytes)", bufferBytes);
		} catch (Exception e) {
			log.debug("Failed to open audio playback line", e);
			line = null;
		}
	}

	private void playbackTick() {
		if (!running.get()) {
			return;
		}

		try {
			float[] mixBuffer = new float[FRAME_SIZE_SAMPLES];
			int senderCount = 0;

			long now = System.currentTimeMillis();
			for (Map.Entry<String, SpeakerState> entry : speakers.entrySet()) {
				SpeakerState state = entry.getValue();

				if (now - state.lastReceiveTime > 1500) {
					activeSpeakers.remove(entry.getKey());
					continue;
				}

				Integer distance = nearbyDistances.get(entry.getKey());
				if (distance == null) {
					activeSpeakers.remove(entry.getKey());
					continue;
				}

				float distScale = 1.0f - (float) (Math.log(distance + 1) / Math.log(16));
				distScale = Math.max(0f, distScale);
				if (distScale <= 0f) {
					activeSpeakers.remove(entry.getKey());
					continue;
				}

				if (!state.jitterBuffer.isReady() || !state.jitterBuffer.canPoll()) {
					continue;
				}

				byte[] payload = state.jitterBuffer.poll();

				try {
					if (payload == null)
						continue;

					AudioCodec.decode(payload, 0, payload.length, decodedBuffer);

					for (int i = 0; i < decodedBuffer.length; i++) {
						if (i < mixBuffer.length) {
							mixBuffer[i] += decodedBuffer[i] * distScale;
						}
					}
					senderCount++;
					activeSpeakers.add(entry.getKey());
				} catch (Exception e) {
					log.debug("Audio processing error for sender {}: {}", entry.getKey(), e.getMessage());
				}
			}

			if (senderCount > 0) {
				double volume = config.outputVolume() / 100.0;

				float maxVal = 0;
				for (float v : mixBuffer) {
					maxVal = Math.max(maxVal, Math.abs(v));
				}

				float masterScale = 1.0f;
				if (maxVal > 32767) {
					masterScale = 32767f / maxVal;
				}

				for (int i = 0; i < mixBuffer.length; i++) {
					loopbackShortBuffer[i] = (short) Math.max(-32768, Math.min(32767, mixBuffer[i] * masterScale * volume));
				}

				AudioDeviceManager.shortsToBytes(loopbackShortBuffer, outputByteBuffer);
				line.write(outputByteBuffer, 0, outputByteBuffer.length);
			}

			// Cleanup speaker
			speakers.entrySet().removeIf(e -> {
				if (now - e.getValue().lastReceiveTime > 8000) {
					activeSpeakers.remove(e.getKey());
					e.getValue().jitterBuffer.reset();
					return true;
				}
				return false;
			});
		} catch (Exception e) {
			log.debug("Error in audio playback tick", e);
		}
	}

	public void shutdown() {
		running.set(false);
		if (playbackTask != null) {
			playbackTask.cancel(true);
			playbackTask = null;
		}
		closeLine();
		if (scheduler != null) {
			scheduler.shutdownNow();
			scheduler = null;
		}
	}

	public void closeLine() {
		if (line != null) {
			try {
				line.stop();
				line.close();
			} catch (Exception e) {
				log.debug("Error closing playback line", e);
			}
			line = null;
		}
	}

	private static class SpeakerState {
		final JitterBuffer jitterBuffer = new JitterBuffer();
		volatile long lastReceiveTime = System.currentTimeMillis();
	}
}

package com.voicescape;

